DEBUG_LEVEL = 0
DEBUG_COMPONENTS = []

for arg in sys.argv:
    if arg == "--debug":
        DEBUG_LEVEL = max(DEBUG_LEVEL, 1)
    elif arg.startswith("--debug="):
        value = arg.split("=", 1)[1]
        if value.isdigit():
            DEBUG_LEVEL = max(DEBUG_LEVEL, int(value))
        else:
            DEBUG_COMPONENTS.extend(value.split(","))

QUIET_MODE = "--quiet" in sys.argv or "-q" in sys.argv

