    # UI‑Aufbau
    # -------------------------------------------------------------------------
    def build_ui(self) -> None:
        """Erstellt die Benutzeroberfläche des Dialogs."""
        # Prüfen, ob Ollama erreichbar ist
        if not self.summarizer.is_server_reachable():
            DarkMessageBox.showwarning(
                "Ollama nicht erreichbar",
                "Der Ollama-Server läuft nicht oder ist nicht erreichbar.\n"
                "Bitte starte 'ollama serve' und versuche es erneut.",
                parent=self.parent,
            )
            self.close()
            return

        # 1. Modell‑Auswahl
        model_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        model_frame.pack(fill="x", pady=5)

        tk.Label(
            model_frame,
            text="Modell:",
            bg=CURRENT_THEME.BG_PRIMARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
        ).pack(side="left")

        self.model_var = tk.StringVar(value=self.saved_model)
        available = self.summarizer.get_available_models()
        if available:
            # Bevorzugte Modelle zuerst anzeigen
            preferred = ["qwen2.5:7b", "glm4:9b", "llama3.1:8b"]
            values = []
            for pref in preferred:
                if pref in available:
                    values.append(pref)
            for m in available:
                if m not in values:
                    values.append(m)
            self.model_combo = ttk.Combobox(
                model_frame,
                textvariable=self.model_var,
                values=values,
                width=20,
                state="readonly",
                style="Dark.TCombobox",
            )
            if self.model_var.get() not in values and values:
                self.model_var.set(values[0])
        else:
            self.model_combo = ttk.Combobox(
                model_frame,
                textvariable=self.model_var,
                values=["(keine Modelle gefunden)"],
                width=20,
                state="disabled",
                style="Dark.TCombobox",
            )
            self.model_var.set("(keine Modelle)")
        self.model_combo.pack(side="left", padx=10)
        ToolTip(self.model_combo, "Wähle das Ollama-Modell für die Zusammenfassung")

        # 2. Temperatur (Kreativität)
