    # -------------------------------------------------------------------------
    #  Sektion: Text-to-Speech
    # -------------------------------------------------------------------------
    def _create_tts_section(self, row: int) -> None:
        tts_frame = tk.LabelFrame(
            self.settings_frame,
            text="🔊 Text-to-Speech",
            padx=10,
            pady=8,
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8, "bold"),
        )
        tts_frame.grid(row=row, column=0, sticky="ew", pady=5, padx=5)
        tts_frame.columnconfigure(1, weight=1)
        tts_frame.columnconfigure(3, weight=1)

        # Zeile 0: Engine und Stimme
        tk.Label(
            tts_frame,
            text="TTS Engine:",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        ).grid(row=0, column=0, sticky="w", pady=2, padx=2)
        self.tts_engine_combo = ttk.Combobox(
            tts_frame,
            textvariable=self.tts_engine_var,
            values=["piper", "pyttsx3"],
            width=self.COMBO_WIDTH_SMALL,
            state="readonly",
            style="Dark.TCombobox",
        )
        self.tts_engine_combo.grid(row=0, column=1, sticky="w", pady=2, padx=2)
        ToolTip(
            self.tts_engine_combo,
            "Wählen Sie die TTS-Engine (Piper = bessere Qualität, benötigt installierte Stimme)",
        )

        tk.Label(
            tts_frame,
            text="Stimme (Piper):",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        ).grid(row=0, column=2, sticky="w", pady=2, padx=2)
        self.tts_voice_combo = ttk.Combobox(
            tts_frame,
            textvariable=self.tts_voice_var,
            values=self.available_piper_voices,
            width=self.COMBO_WIDTH_LARGE,
            state="readonly",
            style="Dark.TCombobox",
        )
        self.tts_voice_combo.grid(row=0, column=3, sticky="w", pady=2, padx=2)
        ToolTip(
            self.tts_voice_combo,
            "Installierte Piper-Stimme (wird automatisch erkannt)",
        )

        # Zeile 1: Geschwindigkeit
        tk.Label(
            tts_frame,
            text="Geschwindigkeit:",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        ).grid(row=1, column=0, sticky="w", pady=2, padx=2)
        self.tts_length_scale_scale = tk.Scale(
            tts_frame,
            from_=0.5,
            to=1.5,
            resolution=0.05,
            orient=tk.HORIZONTAL,
            variable=self.tts_length_scale_var,
            length=self.SCALE_LENGTH,
            showvalue=True,
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            troughcolor=self.gui.current_theme.BG_TERTIARY,
            font=("Segoe UI", 8),
        )
        self.tts_length_scale_scale.grid(row=1, column=1, sticky="ew", pady=2, padx=2)
        ToolTip(
            self.tts_length_scale_scale, "Sprechgeschwindigkeit (niedriger = langsamer)"
        )

        # Zeile 2: Satzpause
        tk.Label(
            tts_frame,
            text="Satzpause (s):",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        ).grid(row=2, column=0, sticky="w", pady=2, padx=2)
        self.tts_sentence_silence_scale = tk.Scale(
            tts_frame,
            from_=0.0,
            to=0.5,
            resolution=0.01,
            orient=tk.HORIZONTAL,
            variable=self.tts_sentence_silence_var,
            length=self.SCALE_LENGTH,
            showvalue=True,
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            troughcolor=self.gui.current_theme.BG_TERTIARY,
            font=("Segoe UI", 8),
        )
        self.tts_sentence_silence_scale.grid(
            row=2, column=1, sticky="ew", pady=2, padx=2
        )
        ToolTip(self.tts_sentence_silence_scale, "Pause zwischen Sätzen in Sekunden")

        # Zeile 3: Test-Button und Status
        btn_frame = tk.Frame(tts_frame, bg=self.gui.current_theme.BG_SECONDARY)
        btn_frame.grid(row=3, column=0, columnspan=4, pady=5)

        test_btn = tk.Button(
            btn_frame,
            text="🔊 Test",
            command=self._test_tts,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
            padx=10,
            cursor="hand2",
        )
        test_btn.pack(side="left", padx=5)

        self.tts_test_status = tk.Label(
            btn_frame,
            text="",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_SECONDARY,
            font=("Segoe UI", 7),
        )
        self.tts_test_status.pack(side="left", fill="x", expand=True, padx=5)

    # -------------------------------------------------------------------------
    #  Sektion: Optionale Python-Pakete
    # -------------------------------------------------------------------------
    def _create_optional_section(self, row: int) -> None:
        optional_frame = tk.LabelFrame(
            self.settings_frame,
            text="📦 Optionale Python-Pakete",
            padx=10,
            pady=8,
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8, "bold"),
        )
        optional_frame.grid(row=row, column=0, sticky="ew", pady=5, padx=5)
        optional_frame.columnconfigure(1, weight=1)

        packages = [
            ("deep-translator", TRANSLATOR_AVAILABLE),
            ("faster-whisper", WHISPER_AVAILABLE),
            ("psutil", FastLazyLoader.is_available("psutil")),
            ("pynvml", importlib.util.find_spec("pynvml") is not None),
            ("argos-translate", ARGOS_AVAILABLE),
        ]

        for i, (name, available) in enumerate(packages):
            status = "✅" if available else "❌"
            lbl = tk.Label(
                optional_frame,
                text=f"{status} {name}",
                anchor="w",
                bg=self.gui.current_theme.BG_SECONDARY,
                fg=self.gui.current_theme.TEXT_PRIMARY,
                font=("Segoe UI", 8),
            )
            lbl.grid(row=i, column=0, sticky="w", pady=1, padx=5)
            self.package_labels.append((name, lbl))

        install_btn = tk.Button(
            optional_frame,
            text="📦 Fehlende Pakete installieren",
            command=self._open_install_dialog,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        )
        install_btn.grid(row=len(packages), column=0, pady=10)

